def find_task_dirs(root, exclude_prefixes=None):
    """Find directories that look like task directories"""
    if exclude_prefixes is None:
        exclude_prefixes = []

    results = []
    for name in os.listdir(root):
        full_path = os.path.join(root, name)
        if os.path.isdir(full_path):
            skipped = any(exclude for ex in exclude_prefixes if name.startswith(ex))
            if not skipped:
                results.append(name)
    return results

